// Prepara las dos consultas de Zoho: los últimos 7 días y los 7 anteriores.
// COQL pide las fechas con zona horaria: se usa UTC.
const now = Date.now();
const day = 24 * 3600 * 1000;
const stamp = (ms) => new Date(ms).toISOString().replace(/\.\d{3}Z$/, '+00:00');

const select = 'select Landing_Page, YB_Segment, YB_Event, UTM_Source, Consent_Status, Created_Time from Leads';
const thisWeek = `${select} where Created_Time >= '${stamp(now - 7 * day)}' limit 200`;
const lastWeek = `${select} where Created_Time >= '${stamp(now - 14 * day)}' and Created_Time < '${stamp(now - 7 * day)}' limit 200`;

return [
  { json: { label: 'this', query: thisWeek, from: stamp(now - 7 * day), to: stamp(now) } },
  { json: { label: 'previous', query: lastWeek, from: stamp(now - 14 * day), to: stamp(now - 7 * day) } },
];

// Resumen semanal de contactos nuevos en Zoho, con la semana anterior al lado.
// Cuenta lo que Zoho tiene. NO calcula la tasa de conversión de cada landing page:
// para eso hacen falta las visitas, que salen de la herramienta de analítica.
const cfg = (name, fallback) => {
  try {
    return $vars[name] || fallback;
  } catch (e) {
    return fallback;
  }
};
const TEAM = String(cfg('YB_SUMMARY_TEAM_EMAIL', '')).trim();
if (!TEAM) return [];

const NAVY = '#031f3c';
const SAND = '#b8a27a';
const IVORY = '#f6f3ec';

const responses = $input.all();
const windows = $('Fechas').all();
const esc = (value) =>
  String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

// Una respuesta vacía (204) no trae "data": cuenta como cero contactos.
const rowsOf = (i) => (responses[i] && Array.isArray(responses[i].json.data) ? responses[i].json.data : []);
const moreThan = (i) => Boolean(responses[i] && responses[i].json.info && responses[i].json.info.more_records);
const thisWeek = rowsOf(0);
const lastWeek = rowsOf(1);

const tally = (rows, field) => {
  const counts = {};
  for (const row of rows) {
    const key = String(row[field] || '(none)').slice(0, 60);
    counts[key] = (counts[key] || 0) + 1;
  }
  return counts;
};

const section = (title, field) => {
  const a = tally(thisWeek, field);
  const b = tally(lastWeek, field);
  const keys = [...new Set([...Object.keys(a), ...Object.keys(b)])].sort((x, y) => (b[y] || 0) + (a[y] || 0) - ((b[x] || 0) + (a[x] || 0)));
  if (!keys.length) return '';
  const rows = keys
    .map(
      (key) =>
        `<tr><td style="padding:7px 12px 7px 0;border-bottom:1px solid #efeadf;font-size:14px;color:#1f2d3d">${esc(key)}</td>` +
        `<td style="padding:7px 12px;border-bottom:1px solid #efeadf;font-size:14px;color:#1f2d3d;text-align:right">${a[key] || 0}</td>` +
        `<td style="padding:7px 0;border-bottom:1px solid #efeadf;font-size:14px;color:#5b6772;text-align:right">${b[key] || 0}</td></tr>`,
    )
    .join('');
  return `<p style="margin:24px 0 6px 0;font-size:11px;letter-spacing:1.2px;text-transform:uppercase;color:#8a7448">${esc(title)}</p>
<table width="100%" cellpadding="0" cellspacing="0"><tr><td></td><td style="padding:0 12px;font-size:11px;color:#5b6772;text-align:right">This week</td><td style="font-size:11px;color:#5b6772;text-align:right">Previous</td></tr>${rows}</table>`;
};

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
const total = plural(thisWeek.length, 'new contact', 'new contacts');
const granted = thisWeek.filter((row) => row.Consent_Status === 'granted').length;
const notes = [];
if (moreThan(0) || moreThan(1)) notes.push('Zoho returned the maximum of 200 contacts for a week, so the real totals may be higher.');
if (!windows.length) notes.push('The date window could not be read.');

const html = `<!doctype html><html><body style="margin:0;padding:0;background:${IVORY}">
<table width="100%" cellpadding="0" cellspacing="0" style="background:${IVORY};padding:32px 0"><tr><td align="center">
<table width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#ffffff;border:1px solid #e4dfd3">
<tr><td style="background:${NAVY};padding:28px 36px">
<p style="margin:0;font-family:Arial,sans-serif;font-size:11px;letter-spacing:4px;text-transform:uppercase;color:${SAND}">YB University</p>
<h1 style="margin:10px 0 0 0;font-family:Georgia,serif;font-weight:normal;font-size:26px;line-height:1.2;color:#ffffff">Weekly summary</h1>
</td></tr>
<tr><td style="padding:32px 36px 28px 36px;font-family:Arial,sans-serif">
<p style="margin:0 0 4px 0;font-size:30px;font-family:Georgia,serif;color:#1f2d3d">${total}</p>
<p style="margin:0 0 8px 0;font-size:14px;color:#5b6772">Previous 7 days: ${lastWeek.length}. Agreed to program updates this week: ${granted}.</p>
${section('By landing page', 'Landing_Page')}
${section('By segment', 'YB_Segment')}
${section('By type of form', 'YB_Event')}
${section('By campaign source (utm_source)', 'UTM_Source')}
${notes.map((n) => `<p style="margin:20px 0 0 0;font-size:12px;color:#8a7448">${esc(n)}</p>`).join('')}
<p style="margin:24px 0 0 0;font-size:12px;line-height:1.6;color:#5b6772">These are contacts counted in Zoho CRM. Conversion rate per page needs visits, which come from the analytics tool.</p>
</td></tr>
<tr><td style="background:${SAND};height:4px;font-size:0;line-height:0">&nbsp;</td></tr>
</table></td></tr></table></body></html>`;

return [{ json: { to: TEAM, subject: `[YB] Weekly summary: ${total}`, html } }];
